/* secp256k1_device.cuh
 *
 * Device-side secp256k1 field/scalar arithmetic and point operations.
 * 256-bit values represented as 8x32-bit limbs (little-endian limb
 * order: v[0] is least significant).
 *
 * UNTESTED until validate_scalar_mult (see below) passes - do not
 * trust results from any kernel using this file until that check
 * passes on real hardware.
 */

#if 1


#include <cstdint>

struct u256 { uint32_t v[8]; };

__device__ __forceinline__ u256 u256_from_be_bytes(const unsigned char *b){
    u256 r;
    for(int i=0;i<8;++i){
        int off = (7-i)*4;
        r.v[i] = ((uint32_t)b[off]<<24)|((uint32_t)b[off+1]<<16)|
                 ((uint32_t)b[off+2]<<8)|((uint32_t)b[off+3]);
    }
    return r;
}

__device__ __forceinline__ void u256_to_be_bytes(const u256 &a, unsigned char *out){
    for(int i=0;i<8;++i){
        int off = (7-i)*4;
        out[off]   = (unsigned char)(a.v[i]>>24);
        out[off+1] = (unsigned char)(a.v[i]>>16);
        out[off+2] = (unsigned char)(a.v[i]>>8);
        out[off+3] = (unsigned char)(a.v[i]);
    }
}

__device__ __forceinline__ bool u256_is_zero(const u256 &a){
    uint32_t r = 0;
    for(int i=0;i<8;++i) r |= a.v[i];
    return r == 0;
}

__device__ __forceinline__ int u256_cmp(const u256 &a, const u256 &b){
    for(int i=7;i>=0;--i){
        if(a.v[i] != b.v[i]) return a.v[i] < b.v[i] ? -1 : 1;
    }
    return 0;
}

/* c = a + b, returns carry (0 or 1) */
__device__ __forceinline__ uint32_t u256_add(u256 &c, const u256 &a, const u256 &b){
    uint64_t carry = 0;
    for(int i=0;i<8;++i){
        uint64_t s = (uint64_t)a.v[i] + b.v[i] + carry;
        c.v[i] = (uint32_t)s;
        carry = s >> 32;
    }
    return (uint32_t)carry;
}

/* c = a - b, returns borrow (0 or 1) */
__device__ __forceinline__ uint32_t u256_sub(u256 &c, const u256 &a, const u256 &b){
    int64_t borrow = 0;
    for(int i=0;i<8;++i){
        int64_t d = (int64_t)a.v[i] - b.v[i] - borrow;
        if(d < 0){ d += ((int64_t)1<<32); borrow = 1; } else borrow = 0;
        c.v[i] = (uint32_t)d;
    }
    return (uint32_t)borrow;
}

/* Field modulus P = 2^256 - 2^32 - 977 (secp256k1) */
__device__ __constant__ u256 FIELD_P = {{
    0xFFFFFC2F, 0xFFFFFFFE, 0xFFFFFFFF, 0xFFFFFFFF,
    0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF
}};

/* Curve order N */
__device__ __constant__ u256 CURVE_N = {{
    0xD0364141, 0xBFD25E8C, 0xAF48A03B, 0xBAAEDCE6,
    0xFFFFFFFE, 0xFFFFFFFF, 0xFFFFFFFF, 0xFFFFFFFF
}};

__device__ __forceinline__ u256 mod_add(const u256 &a, const u256 &b, const u256 &m){
    u256 c;
    uint32_t carry = u256_add(c, a, b);
    if(carry || u256_cmp(c, m) >= 0){
        u256 t;
        u256_sub(t, c, m);
        c = t;
    }
    return c;
}

__device__ __forceinline__ u256 mod_sub(const u256 &a, const u256 &b, const u256 &m){
    u256 c;
    uint32_t borrow = u256_sub(c, a, b);
    if(borrow){
        u256 t;
        u256_add(t, c, m);
        c = t;
    }
    return c;
}

/* 512-bit product of two 256-bit numbers, as 16x32-bit limbs */
__device__ __forceinline__ void u256_mul_512(uint32_t r[16], const u256 &a, const u256 &b){
    for(int i=0;i<16;++i) r[i]=0;
    for(int i=0;i<8;++i){
        uint64_t carry = 0;
        for(int j=0;j<8;++j){
            uint64_t p = (uint64_t)a.v[i]*b.v[j] + r[i+j] + carry;
            r[i+j] = (uint32_t)p;
            carry = p >> 32;
        }
        r[i+8] += (uint32_t)carry;
    }
}

/* Reduce a 512-bit value mod m via shift-and-subtract long division,
 * operating on full 512-bit (16-limb) representations throughout to
 * avoid the bit-serial approach's carry bug found during validation
 * (confirmed via (P-1)^2 mod P test - see project notes). Iterates
 * k from 256 down to 0, subtracting (m << k) whenever the current
 * value is >= that shifted modulus. */

__device__ __forceinline__ void u512_shift_mod(uint32_t dst[16], const u256 &m, int k){
    for(int i=0;i<16;++i) dst[i]=0;
    int limb_shift = k / 32;
    int bit_shift = k % 32;

    for(int i=0;i<8;++i){
        int dst_idx = i + limb_shift;
        if(dst_idx >= 16) continue;
        uint64_t val = ((uint64_t)m.v[i]) << bit_shift;
        dst[dst_idx] |= (uint32_t)val;
        if(bit_shift > 0 && dst_idx+1 < 16){
            dst[dst_idx+1] |= (uint32_t)(val >> 32);
        }
    }
}

__device__ __forceinline__ int u512_cmp(const uint32_t a[16], const uint32_t b[16]){
    for(int i=15;i>=0;--i){
        if(a[i]!=b[i]) return a[i]<b[i] ? -1 : 1;
    }
    return 0;
}

__device__ __forceinline__ void u512_sub_inplace(uint32_t a[16], const uint32_t b[16]){
    int64_t borrow=0;
    for(int i=0;i<16;++i){
        int64_t d = (int64_t)a[i] - b[i] - borrow;
        if(d<0){ d += ((int64_t)1<<32); borrow=1; } else borrow=0;
        a[i]=(uint32_t)d;
    }
}

__device__ __forceinline__ u256 reduce_512_mod(const uint32_t r[16], const u256 &m){
    uint32_t val[16];
    for(int i=0;i<16;++i) val[i]=r[i];

    for(int k = 512-256; k >= 0; --k){
        uint32_t shifted[16];
        u512_shift_mod(shifted, m, k);
        if(u512_cmp(val, shifted) >= 0){
            u512_sub_inplace(val, shifted);
        }
    }

    u256 result;
    for(int i=0;i<8;++i) result.v[i]=val[i];
    return result;
}


#define SECP256K1_C 0x1000003D1ULL

__device__ __forceinline__ void u256_mul_small(uint32_t out[10], const u256 &a, uint64_t c){
    for(int i=0;i<10;++i) out[i]=0;
    unsigned __int128 carry=0;
    for(int i=0;i<8;++i){
        unsigned __int128 p=(unsigned __int128)a.v[i]*c+carry;
        out[i]=(uint32_t)p; carry=p>>32;
    }
    out[8]=(uint32_t)carry;
    out[9]=(uint32_t)(carry>>32);
}

__device__ __forceinline__ void mul64_to_limbs10(uint32_t out[10], unsigned __int128 hi_int, uint64_t c){
    for(int i=0;i<10;++i) out[i]=0;
    unsigned __int128 prod=hi_int*(unsigned __int128)c;
    for(int i=0;i<10 && prod!=0;++i){ out[i]=(uint32_t)(prod&0xFFFFFFFFULL); prod>>=32; }
}

__device__ __forceinline__ u256 fast_reduce_secp256k1(const uint32_t r[16]){
    uint32_t acc[10];
    for(int i=0;i<8;++i) acc[i]=r[i];
    acc[8]=0; acc[9]=0;
    u256 hi; for(int i=0;i<8;++i) hi.v[i]=r[i+8];
    bool first=true;
    unsigned __int128 hi_int=0;
    int iters=0;
    while(iters<30){
        iters++;
        uint32_t prodlimbs[10];
        if(first){
            bool hz=true; for(int i=0;i<8;++i) if(hi.v[i]!=0) hz=false;
            if(hz) break;
            u256_mul_small(prodlimbs,hi,SECP256K1_C);
            first=false;
        } else {
            if(hi_int==0) break;
            mul64_to_limbs10(prodlimbs,hi_int,SECP256K1_C);
        }
        uint64_t carry=0;
        uint32_t new_acc[10];
        for(int i=0;i<10;++i){
            uint64_t s=(uint64_t)acc[i]+prodlimbs[i]+carry;
            new_acc[i]=(uint32_t)s; carry=s>>32;
        }
        for(int i=0;i<10;++i) acc[i]=new_acc[i];
        hi_int=((unsigned __int128)acc[9]<<32)|acc[8];
        acc[8]=0; acc[9]=0;
    }
    u256 result; for(int i=0;i<8;++i) result.v[i]=acc[i];
    while(u256_cmp(result,FIELD_P)>=0){ u256 t; u256_sub(t,result,FIELD_P); result=t; }
    return result;
}

__device__ __forceinline__ u256 mod_mul(const u256 &a, const u256 &b, const u256 &m){
    uint32_t r[16];
    u256_mul_512(r, a, b);
    bool is_field_p = true;
    for(int i=0;i<8;++i) if(m.v[i]!=FIELD_P.v[i]){ is_field_p=false; break; }
    if(is_field_p) return fast_reduce_secp256k1(r);
    return reduce_512_mod(r, m);
}

/* Modular exponentiation (square-and-multiply): base^exp mod m.
 * exp given as a u256. Used for modular inverse via Fermat
 * (a^(m-2) mod m) since m (both P and N here) is prime. */
__device__ __forceinline__ u256 mod_pow(u256 base, u256 exp, const u256 &m){
    u256 result; result.v[0]=1; for(int i=1;i<8;++i) result.v[i]=0;

    for(int limb=0; limb<8; ++limb){
        for(int bit=0; bit<32; ++bit){
            if((exp.v[limb] >> bit) & 1){
                result = mod_mul(result, base, m);
            }
            base = mod_mul(base, base, m);
        }
    }
    return result;
}

__device__ __forceinline__ u256 mod_inverse(const u256 &a, const u256 &m){
    /* m - 2 */
    u256 two; two.v[0]=2; for(int i=1;i<8;++i) two.v[i]=0;
    u256 exp;
    u256_sub(exp, m, two);
    return mod_pow(a, exp, m);
}

/* ============ EC point operations (affine, over F_P) ============ */

struct ECPoint {
    u256 x, y;
    bool infinity;
};

__device__ __forceinline__ ECPoint point_double(const ECPoint &p){
    if(p.infinity) return p;

    u256 two_y = mod_add(p.y, p.y, FIELD_P);
    u256 inv_two_y = mod_inverse(two_y, FIELD_P);

    u256 x_sq = mod_mul(p.x, p.x, FIELD_P);
    u256 three_x_sq = mod_add(mod_add(x_sq, x_sq, FIELD_P), x_sq, FIELD_P);
    u256 lam = mod_mul(three_x_sq, inv_two_y, FIELD_P);

    u256 lam_sq = mod_mul(lam, lam, FIELD_P);
    u256 x3 = mod_sub(mod_sub(lam_sq, p.x, FIELD_P), p.x, FIELD_P);
    u256 y3 = mod_sub(mod_mul(lam, mod_sub(p.x, x3, FIELD_P), FIELD_P), p.y, FIELD_P);

    ECPoint r; r.x=x3; r.y=y3; r.infinity=false;
    return r;
}

__device__ __forceinline__ ECPoint point_add(const ECPoint &p1, const ECPoint &p2){
    if(p1.infinity) return p2;
    if(p2.infinity) return p1;

    if(u256_cmp(p1.x, p2.x) == 0){
        u256 ysum = mod_add(p1.y, p2.y, FIELD_P);
        if(u256_is_zero(ysum)){
            ECPoint r; r.infinity = true; return r;
        }
        return point_double(p1);
    }

    u256 dx = mod_sub(p2.x, p1.x, FIELD_P);
    u256 dy = mod_sub(p2.y, p1.y, FIELD_P);
    u256 inv_dx = mod_inverse(dx, FIELD_P);
    u256 lam = mod_mul(dy, inv_dx, FIELD_P);

    u256 lam_sq = mod_mul(lam, lam, FIELD_P);
    u256 x3 = mod_sub(mod_sub(lam_sq, p1.x, FIELD_P), p2.x, FIELD_P);
    u256 y3 = mod_sub(mod_mul(lam, mod_sub(p1.x, x3, FIELD_P), FIELD_P), p1.y, FIELD_P);

    ECPoint r; r.x=x3; r.y=y3; r.infinity=false;
    return r;
}

__device__ __forceinline__ ECPoint scalar_mul(const u256 &k, const ECPoint &p){
    ECPoint result; result.infinity = true;
    ECPoint addend = p;

    for(int limb=0; limb<8; ++limb){
        for(int bit=0; bit<32; ++bit){
            if((k.v[limb] >> bit) & 1){
                result = point_add(result, addend);
            }
            addend = point_double(addend);
        }
    }
    return result;
}


struct JPoint { u256 x, y, z; bool infinity; };

__device__ __forceinline__ JPoint jacobian_double(const JPoint &p){
    if(p.infinity) return p;
    u256 A = mod_mul(p.x, p.x, FIELD_P);
    u256 B = mod_mul(p.y, p.y, FIELD_P);
    u256 C = mod_mul(B, B, FIELD_P);
    u256 xB = mod_add(p.x, B, FIELD_P);
    u256 xB2 = mod_mul(xB, xB, FIELD_P);
    u256 D_inner = mod_sub(mod_sub(xB2, A, FIELD_P), C, FIELD_P);
    u256 D = mod_add(D_inner, D_inner, FIELD_P);
    u256 E = mod_add(mod_add(A,A,FIELD_P), A, FIELD_P);
    u256 F = mod_mul(E, E, FIELD_P);
    u256 twoD = mod_add(D, D, FIELD_P);
    u256 X3 = mod_sub(F, twoD, FIELD_P);
    u256 DX3 = mod_sub(D, X3, FIELD_P);
    u256 EDX3 = mod_mul(E, DX3, FIELD_P);
    u256 eightC = mod_add(mod_add(mod_add(C,C,FIELD_P),mod_add(C,C,FIELD_P),FIELD_P),
                           mod_add(mod_add(C,C,FIELD_P),mod_add(C,C,FIELD_P),FIELD_P),FIELD_P);
    u256 Y3 = mod_sub(EDX3, eightC, FIELD_P);
    u256 yz = mod_mul(p.y, p.z, FIELD_P);
    u256 Z3 = mod_add(yz, yz, FIELD_P);
    JPoint r; r.x=X3; r.y=Y3; r.z=Z3; r.infinity=false;
    return r;
}

__device__ __forceinline__ JPoint jacobian_add(const JPoint &p1, const JPoint &p2){
    if(p1.infinity) return p2;
    if(p2.infinity) return p1;
    u256 Z1Z1 = mod_mul(p1.z, p1.z, FIELD_P);
    u256 Z2Z2 = mod_mul(p2.z, p2.z, FIELD_P);
    u256 U1 = mod_mul(p1.x, Z2Z2, FIELD_P);
    u256 U2 = mod_mul(p2.x, Z1Z1, FIELD_P);
    u256 Z2Z2Z2 = mod_mul(Z2Z2, p2.z, FIELD_P);
    u256 Z1Z1Z1 = mod_mul(Z1Z1, p1.z, FIELD_P);
    u256 S1 = mod_mul(p1.y, Z2Z2Z2, FIELD_P);
    u256 S2 = mod_mul(p2.y, Z1Z1Z1, FIELD_P);
    if(u256_cmp(U1,U2)==0){
        if(u256_cmp(S1,S2)==0) return jacobian_double(p1);
        JPoint inf; inf.infinity=true; return inf;
    }
    u256 H = mod_sub(U2, U1, FIELD_P);
    u256 twoH = mod_add(H,H,FIELD_P);
    u256 I = mod_mul(twoH, twoH, FIELD_P);
    u256 J = mod_mul(H, I, FIELD_P);
    u256 S2S1 = mod_sub(S2, S1, FIELD_P);
    u256 r = mod_add(S2S1, S2S1, FIELD_P);
    u256 V = mod_mul(U1, I, FIELD_P);
    u256 r2 = mod_mul(r, r, FIELD_P);
    u256 twoV = mod_add(V,V,FIELD_P);
    u256 X3 = mod_sub(mod_sub(r2, J, FIELD_P), twoV, FIELD_P);
    u256 VX3 = mod_sub(V, X3, FIELD_P);
    u256 rVX3 = mod_mul(r, VX3, FIELD_P);
    u256 S1J = mod_mul(S1, J, FIELD_P);
    u256 twoS1J = mod_add(S1J, S1J, FIELD_P);
    u256 Y3 = mod_sub(rVX3, twoS1J, FIELD_P);
    u256 z1z2 = mod_add(p1.z, p2.z, FIELD_P);
    u256 z1z2sq = mod_mul(z1z2, z1z2, FIELD_P);
    u256 Z3_inner = mod_sub(mod_sub(z1z2sq, Z1Z1, FIELD_P), Z2Z2, FIELD_P);
    u256 Z3 = mod_mul(Z3_inner, H, FIELD_P);
    JPoint r_out; r_out.x=X3; r_out.y=Y3; r_out.z=Z3; r_out.infinity=false;
    return r_out;
}

__device__ __forceinline__ JPoint jacobian_scalar_mul(const u256 &k, const ECPoint &p_affine){
    JPoint p; p.x=p_affine.x; p.y=p_affine.y;
    u256 one; one.v[0]=1; for(int i=1;i<8;++i) one.v[i]=0;
    p.z=one; p.infinity=p_affine.infinity;
    JPoint result; result.infinity=true;
    JPoint addend = p;
    for(int limb=0; limb<8; ++limb){
        for(int bit=0; bit<32; ++bit){
            if((k.v[limb]>>bit)&1) result = jacobian_add(result, addend);
            addend = jacobian_double(addend);
        }
    }
    return result;
}

__device__ __forceinline__ ECPoint jacobian_to_affine(const JPoint &p){
    if(p.infinity){ ECPoint r; r.infinity=true; return r; }
    u256 zinv = mod_inverse(p.z, FIELD_P);
    u256 zinv2 = mod_mul(zinv, zinv, FIELD_P);
    u256 zinv3 = mod_mul(zinv2, zinv, FIELD_P);
    ECPoint r;
    r.x = mod_mul(p.x, zinv2, FIELD_P);
    r.y = mod_mul(p.y, zinv3, FIELD_P);
    r.infinity = false;
    return r;
}

/* ============ Batch (Montgomery) modular inversion, shared across a
 * thread block - validated in C (batch_inv_test.c, 16-value test,
 * matches individual mod_inverse exactly) before this CUDA port.
 *
 * Each thread in the block calls this with its OWN JPoint (possibly
 * infinity). Returns that thread's affine point, having shared ONE
 * total modular inversion across the whole block instead of one per
 * thread. Requires blockDim.x <= MAX_BATCH_THREADS and must be called
 * by ALL threads in the block (uses __syncthreads()).
 * ============ */
#define MAX_BATCH_THREADS 128

/* Shared-memory workspace for batch_jacobian_to_affine, declared ONCE
 * by the kernel and reused across all 3 call sites (avoids the
 * compiler potentially allocating separate shared memory per inlined
 * call site, which would blow the shared-memory budget: 3x this
 * struct's ~24KB would exceed typical 48KB/block limits). */
struct BatchInvWorkspace {
    u256 prefix[MAX_BATCH_THREADS+1];
    u256 z_vals[MAX_BATCH_THREADS];
    u256 inv_z[MAX_BATCH_THREADS];
    u256 total_inv;
};

__device__ ECPoint batch_jacobian_to_affine(const JPoint &p, BatchInvWorkspace &ws){
    int tid = threadIdx.x;
    int n = blockDim.x;

    u256 one; one.v[0]=1; for(int i=1;i<8;++i) one.v[i]=0;
    ws.z_vals[tid] = p.infinity ? one : p.z;

    __syncthreads();

    if(tid == 0){
        ws.prefix[0] = one;
        for(int i=0;i<n;++i){
            ws.prefix[i+1] = mod_mul(ws.prefix[i], ws.z_vals[i], FIELD_P);
        }
        ws.total_inv = mod_inverse(ws.prefix[n], FIELD_P);
    }
    __syncthreads();

    if(tid == 0){
        u256 running = ws.total_inv;
        for(int i=n-1;i>=0;--i){
            ws.inv_z[i] = mod_mul(ws.prefix[i], running, FIELD_P);
            running = mod_mul(running, ws.z_vals[i], FIELD_P);
        }
    }
    __syncthreads();

    ECPoint result;
    if(p.infinity){
        result.infinity = true;
        return result;
    }

    u256 zinv = ws.inv_z[tid];
    u256 zinv2 = mod_mul(zinv, zinv, FIELD_P);
    u256 zinv3 = mod_mul(zinv2, zinv, FIELD_P);
    result.x = mod_mul(p.x, zinv2, FIELD_P);
    result.y = mod_mul(p.y, zinv3, FIELD_P);
    result.infinity = false;
    return result;
}


#endif

