__device__ __forceinline__ uint32_t rotr32(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }

__constant__ uint32_t SHA256_K[64] = {
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
